def main():
    report=json.loads((OUT/'audit-results.json').read_text(encoding='utf-8'))
    catalog=json.loads((OUT.parents[2]/'data/book_catalog/catalog.json').read_text(encoding='utf-8'))
    results=[]
    for row in report['rows']:
        kind,note=NOTES[row['audit_id']]
        b=catalog[row['book_id']-1]
        results.append({'audit_id':row['audit_id'],'cause':kind,'assessment':note,
            'structured_moods':b['mood'],'structured_genres':b['genres'],'structured_pace':b['pace'],
            'raw_semantic_rank':row['raw_semantic_rank'],'semantic_rank':row['corrected_semantic_rank'],
            'full_rank':row['full_rank_before_pool'],'returned_rank':row['returned_rank']})
    supported=[r for r in report['rows'] if r['support']=='present']
    summary={'cases':len(report['rows']),'fully_supported_cases':len(supported),'partially_supported':2,'unsupported':2,
             'supported_target_semantic_top10':sum(r['corrected_semantic_rank']<=10 for r in supported),
             'supported_target_full_top10':sum(r['returned_rank'] is not None and r['returned_rank']<=10 for r in supported),
             'ranking_improves_target':sum(r['full_rank_before_pool']<r['corrected_semantic_rank'] for r in supported),
             'ranking_worsens_target':sum(r['full_rank_before_pool']>r['corrected_semantic_rank'] for r in supported),
             'priority_mixed_cases':['A05','A08','A18'],'semantic_diagnostic_case':['A27'],
             'priority_rule_cases':['A24','A29','A36'],'cause_counts':dict(collections.Counter(r['cause'] for r in results)),
             'scope':'Target-book diagnostic ranks, not exhaustive relevance judgments or unbiased quality estimates.'}
    (OUT/'audit-assessments.json').write_text(json.dumps({'summary':summary,'cases':results},ensure_ascii=False,indent=2),encoding='utf-8')
    lines=['# Разбор 40 запросов','',
           'Ранги относятся к указанной диагностической книге. Для широкого запроса другие книги также могут подходить. '
           'Это аудит выбранных случаев, а не независимая оценка качества или доказательство причинности.', '',
           'Исходный запрос и полный разбор правил, профили десяти семантических и десяти итоговых лидеров, '
           'сигналы и ранги при отключении каждого сигнала сохранены в `audit-results.json`.', '',
           'В столбце «семантика» используется полный исправленный запрос. '
           'В столбце «полный ранг» — все 1000 книг до отсечения. «Выдача» — ранг после порога и ограничения 50.', '',
           '| ID | Запрос | Диагностическая книга | Подтверждение | Семантика | Полный ранг | Выдача |',
           '|---|---|---|---|---:|---:|---:|']
    for r in report['rows']:
        lines.append(f"| {r['audit_id']} | {r['query']} | {r['title']} | {r['support']} | {r['corrected_semantic_rank']} | {r['full_rank_before_pool']} | {r['returned_rank'] or 'нет'} |")
    lines+=['','Для 36 полностью подтверждённых случаев диагностическая книга входит в семантический top-10 '
            'в 22 случаях, а в итоговый top-10 — в 33. Полная формула улучшает её ранг в 24 случаях, ухудшает в двух. '
            'Эти числа нельзя переносить на все пользовательские запросы.', '', '## Индивидуальные выводы','']
    for r in results: lines.append(f"- **{r['audit_id']}** — {r['assessment']}")
    lines+=['','## Что имеет смысл проверять дообучением','',
            'Смешанные промахи A05, A08, A18: сведения есть, а разговорное или атмосферное представление работает слабо. '
            'A27 — сильный диагностический провал чистой семантики, который маскируется остальным поиском. '
            'A07, A16, A19, A21–A23, A26, A28, A32, A34 полезны как типы задач для новых примеров, '
            'но сами эти запросы и их перефразировки резервируются для регрессий и в обучение не идут.', '',
            'Сначала отдельно устранить или учесть ошибки правил A24, A29, A36 и сверить структурированные '
            'настроения A01, A03, A05, A18 с профилями. Подготовить эксперимент так, чтобы версии каталога '
            'и правил были одинаковы для исходной и обученной модели. Текущий аудит ничего в них не меняет.', '',
            'A39–A40 не являются подтверждёнными позитивами. Недостающие утверждения не добавлять без источников.', '',
            'Усечение исключено как причина: профили всех 1000 книг имеют 139–276 токенов с префиксом и '
            'спецтокенами; медиана 208, p95 236, окно текущей модели 512. Потерянных хвостов нет.', '',
            'Отключение сигнала означает обнуление его вклада без перераспределения веса. '
            'Это диагностика текущей формулы, не предлагаемый вариант настройки. Для всех 40 запросов '
            'реконструированный пул полностью совпал с действующей реализацией поиска.']
    (OUT/'AUDIT_REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')

if __name__=='__main__':main()
